  $image = $_FILES['image']['name'];
  $image = time() . "_" . $image;
  $fileinfo = @getimagesize($_FILES["image"]["tmp_name"]);
  if ($fileinfo != '') {
    move_uploaded_file($_FILES['image']['tmp_name'], "../uploads/page/" . $image);
    $query = mysqli_query($conn, "UPDATE `tbl_popup` SET `abt_details`='$detail',`abt_images`='$image'");
  } else {
    $query = mysqli_query($conn, "UPDATE `tbl_popup` SET `abt_details`='$detail'");
  }
  if ($query) {
    $_SESSION['success'] = "Popup Image Updated Successfull";
    header("refresh: 3;");
  } else {
    $_SESSION['error'] = "Something Error";
  }
}
if (isset($_POST['sorts'])) {
  $id = $_POST['id'];
